python - <<'E'
p='web/app/teams/[team_id]/workflow/WorkflowSettingsClient.tsx'
s=open(p).read()
s=s.replace('import { useRouter } from "next/navigation";','import { usePathname, useRouter, useSearchParams } from "next/navigation";')
s=s.replace('''  const [createdId, setCreatedId] = useState<string | null>(null);
''','''  // The draft workflow lives in the URL (?wf=<id>&wfstages=<json names>) so a reload keeps it reachable.
  const pathname = usePathname();
  const search = useSearchParams();
  const createdId = search.get("wf");
  const draftStageNames: string[] = (() => {
    try {
      const v = JSON.parse(search.get("wfstages") ?? "[]");
      return Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : [];
    } catch {
      return [];
    }
  })();
  const [actMapKey, setActMapKey] = useState("");
  const [stageCounts, setStageCounts] = useState<Record<string, number> | null>(null);
  const [actMappings, setActMappings] = useState<Record<string, string>>({});
''')
s=s.replace('''    setCreatedId(created.workflow_id);
    router.refresh();
  }
''','''    const q = new URLSearchParams({
      wf: created.workflow_id,
      wfstages: JSON.stringify(stages.map((st) => st.name)),
    });
    router.replace(`${pathname}?${q.toString()}`);
    setStageCounts(null);
    setActMappings({});
    router.refresh();
  }

  // Active stages that the draft drops or renames.
  const removedStages = (workflow?.stages ?? [])
    .map((s) => s.name)
    .filter((n) => !draftStageNames.includes(n));
  const needsRemap = !!workflow && removedStages.length > 0;
  const populatedRemoved = removedStages.filter((n) => (stageCounts?.[n] ?? 0) > 0);
  const mappingsComplete = populatedRemoved.every((n) => !!actMappings[n]);
  const canActivate = !needsRemap || (stageCounts !== null && mappingsComplete);

  async function onLoadCounts() {
    setBanner(null);
    try {
      const res = await fetch(`/api/web/mindmaps/${encodeURIComponent(actMapKey.trim())}/work-items`, {
        credentials: "include",
      });
      if (!res.ok) {
        setBanner(`Could not load items for map (HTTP ${res.status}).`);
        return;
      }
      const data = (await res.json()) as { items: { current_stage: string | null }[] };
      const counts: Record<string, number> = {};
      for (const it of data.items) if (it.current_stage) counts[it.current_stage] = (counts[it.current_stage] ?? 0) + 1;
      setStageCounts(counts);
    } catch {
      setBanner("Network error; please try again.");
    }
  }
''')
s=s.replace('''    if (!createdId) return;
    const res = await post(`${base}/${encodeURIComponent(createdId)}/activate`);
    if (!res) return;
    setCreatedId(null);
    setToast("Workflow activated.");
    router.refresh();''','''    if (!createdId || !canActivate) return;
    const res = await post(`${base}/${encodeURIComponent(createdId)}/activate`);
    if (!res) return;
    const mappings: Record<string, string> = {};
    for (const n of populatedRemoved) mappings[n] = actMappings[n];
    if (Object.keys(mappings).length > 0) {
      const rm = await post(`${base}/remap`, { map_key: actMapKey.trim(), mappings });
      if (!rm) {
        setBanner("Workflow activated, but remapping items failed; use the Remap form to move items off removed stages.");
        router.refresh();
        return;
      }
    }
    router.replace(pathname);
    setToast("Workflow activated.");
    router.refresh();''')
s=s.replace('''            <button type="button" onClick={onActivate} disabled={busy} className''','''            {needsRemap && (
              <div className="space-y-2 text-sm">
                <p>
                  This workflow removes or renames: {removedStages.join(", ")}. Choose the map whose items
                  to check, then map every removed stage that still holds items.
                </p>
                <div className="flex gap-2">
                  <input
                    className="border rounded px-2 py-1 flex-1"
                    placeholder="Map key"
                    value={actMapKey}
                    onChange={(e) => {
                      setActMapKey(e.target.value);
                      setStageCounts(null);
                    }}
                  />
                  <button type="button" onClick={onLoadCounts} disabled={!actMapKey.trim()} className="border rounded px-3 py-1 disabled:opacity-50">
                    Check items
                  </button>
                </div>
                {stageCounts !== null &&
                  removedStages.map((n) => (
                    <div key={n} className="flex items-center gap-2">
                      <span className="w-40">{n} ({stageCounts[n] ?? 0} items)</span>
                      {(stageCounts[n] ?? 0) > 0 ? (
                        <select
                          className="border rounded px-2 py-1"
                          value={actMappings[n] ?? ""}
                          onChange={(e) => setActMappings({ ...actMappings, [n]: e.target.value })}
                        >
                          <option value="">Move to…</option>
                          {draftStageNames.map((t) => (
                            <option key={t} value={t}>{t}</option>
                          ))}
                        </select>
                      ) : (
                        <span className="text-gray-500">no items</span>
                      )}
                    </div>
                  ))}
              </div>
            )}
            <button type="button" onClick={onActivate} disabled={busy || !canActivate} className''')
open(p,'w').write(s)

